-- Synthetic identities only; the entire proof is rolled back, including authorization fixtures.
begin;
create function pg_temp.pp_id(n integer) returns uuid language sql immutable as $$select ('f9400000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.pp_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.pp_error(statement text,state text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=state then return;end if;raise;end;raise exception 'Expected %',state;end$$;
create function pg_temp.pp_command(n integer default 2,person_version integer default 1,pub_version integer default 0,msg text default '') returns jsonb language sql as $$select jsonb_build_object('commandId',pg_temp.pp_id(n),'personId',pg_temp.pp_id(1),'expectedPersonVersion',person_version,'expectedPublicationVersion',pub_version,'reason',msg,'acknowledgeImpact',true)$$;
grant execute on function pg_temp.pp_id(integer),pg_temp.pp_assert(boolean,text),pg_temp.pp_error(text,text),pg_temp.pp_command(integer,integer,integer,text) to anon,authenticated;
-- Reuse the existing administrator when present, without replacing the human identity.
insert into auth.users(id) values(pg_temp.pp_id(98)),(pg_temp.pp_id(99));
insert into public.admin_access(user_id) select pg_temp.pp_id(98) where not exists(select 1 from public.admin_access);
select set_config('request.jwt.claim.sub',(select user_id::text from public.admin_access),true);
insert into public.persons(id,name) values(pg_temp.pp_id(1),'Ana Silva'),(pg_temp.pp_id(4),'Ana Silva'),(pg_temp.pp_id(5),'Técnico próprio');
insert into private.athletes(person_id,sex,birth_date,federation_registration) values(pg_temp.pp_id(1),'female','1997-01-01','001234'),(pg_temp.pp_id(4),'female',null,null);
insert into public.coaches(person_id) values(pg_temp.pp_id(5));
-- APPLY PROFILE MIGRATION HERE
set local role authenticated;
select pg_temp.pp_assert(public.get_public_player_profile(pg_temp.pp_id(1)) is null,'cadastre never publishes itself');
select public.get_player_profile_proposal(pg_temp.pp_id(1)) as profile_proposal;
select public.get_player_profile_state(pg_temp.pp_id(1)) as empty_profile_state;
select public.confirm_player_profile(pg_temp.pp_command()) as profile_ack;
select pg_temp.pp_assert(public.confirm_player_profile(pg_temp.pp_command())=public.confirm_player_profile(pg_temp.pp_command()),'same command returns original ACK');
select pg_temp.pp_error($q$select public.confirm_player_profile(jsonb_set(pg_temp.pp_command(),'{reason}','"different"'))$q$,'PT409');
select pg_temp.pp_error($q$select public.confirm_player_profile(pg_temp.pp_command(3))$q$,'PT409');
select pg_temp.pp_error($q$select public.confirm_player_profile(jsonb_set(pg_temp.pp_command(6),'{personId}',to_jsonb(pg_temp.pp_id(5))))$q$,'PT404');
select pg_temp.pp_assert(public.get_public_player_profile(pg_temp.pp_id(1))->'person'->'publicBirthYear'='null'::jsonb,'no private birth year inferred');
select pg_temp.pp_assert(not (public.get_public_player_profile(pg_temp.pp_id(1))->'person' ?| array['sex','birthDate','federationRegistration','athlete','coach']),'no private fields in snapshot');
select pg_temp.pp_error('select * from private.player_profile_versions','42501');
select pg_temp.pp_error($q$update public.published_player_profiles set version=99$q$,'42501');
reset role;
update public.persons set name='Ana depois da publicação',biography='Texto opcional 🏀',version=version+1 where id=pg_temp.pp_id(1);
set local role authenticated;
select pg_temp.pp_assert(public.get_public_player_profile(pg_temp.pp_id(1))->'person'->>'name'='Ana Silva','cadastre edit preserves published identity');
select pg_temp.pp_assert((public.get_player_profile_state(pg_temp.pp_id(1))->>'sourceChanged')::boolean,'source change reported privately');
select pg_temp.pp_error($q$select public.confirm_player_profile(pg_temp.pp_command(7,1,1,'Revisão conferida'))$q$,'PT409');
select pg_temp.pp_error($q$select public.confirm_player_profile(pg_temp.pp_command(8,2,1,''))$q$,'PT400');
select public.confirm_player_profile(pg_temp.pp_command(9,2,1,'Revisão conferida')) as revised_profile_ack;
select pg_temp.pp_assert((public.confirm_player_profile(pg_temp.pp_command())->>'version')::int=1,'known replay stays original after newer confirmation');
select public.get_player_profile_state(pg_temp.pp_id(1)) as profile_state;
select public.get_player_profile_version(pg_temp.pp_id(1),1) as profile_version;
select pg_temp.pp_assert(public.get_player_profile_version(pg_temp.pp_id(1),1)->'snapshot'->'person'->>'name'='Ana Silva','history immutable after revision');
select pg_temp.pp_assert(public.get_public_player_profile(pg_temp.pp_id(4)) is null,'homonym not implicitly published');
set local role anon;
select public.get_public_player_profile(pg_temp.pp_id(1)) as public_player_profile;
select pg_temp.pp_assert(public.get_public_player_profile(pg_temp.pp_id(999)) is null,'unknown identity has no public profile');
select pg_temp.pp_error('select public.get_player_profile_proposal(pg_temp.pp_id(1))','42501');
select pg_temp.pp_error('select public.confirm_player_profile(pg_temp.pp_command())','42501');
select pg_temp.pp_error('select * from private.player_profile_commands','42501');
reset role;
select pg_temp.pp_assert((select count(*) from private.player_profile_versions where person_id=pg_temp.pp_id(1))=2,'only confirmations create versions');
select pg_temp.pp_error($q$update private.player_profile_versions set reason='changed' where person_id=pg_temp.pp_id(1)$q$,'PT409');
select pg_temp.pp_error($q$delete from private.player_profile_commands where command_id=pg_temp.pp_id(2)$q$,'PT409');
select pg_temp.pp_error($q$delete from public.persons where id=pg_temp.pp_id(1)$q$,'23503');
select pg_temp.pp_error($q$update public.published_player_profiles set snapshot=jsonb_set(snapshot,'{person,name}','"adulterado"') where person_id=pg_temp.pp_id(1)$q$,'PT409');
select pg_temp.pp_assert(public.get_public_player_profile(pg_temp.pp_id(1))->'person'->>'name'='Ana depois da publicação','failed projection update rolls back');
-- A failure after writing the projection must undo projection, history and receipt together.
create function pg_temp.pp_reject_command() returns trigger language plpgsql as $$begin raise sqlstate 'PT409' using message='synthetic_receipt_failure';end$$;
create trigger pp_reject_command before insert on private.player_profile_commands for each row execute function pg_temp.pp_reject_command();
set local role authenticated;
select pg_temp.pp_error($q$select public.confirm_player_profile(pg_temp.pp_command(10,2,2,'Revisão atômica'))$q$,'PT409');
reset role;
drop trigger pp_reject_command on private.player_profile_commands;
select pg_temp.pp_assert((select count(*) from private.player_profile_versions where person_id=pg_temp.pp_id(1))=2 and (select count(*) from private.player_profile_commands where person_id=pg_temp.pp_id(1))=2 and (public.get_public_player_profile(pg_temp.pp_id(1))->>'version')::int=2,'failure leaves no history, receipt or projection');
select pg_temp.pp_assert(not has_table_privilege('anon','public.published_player_profiles','INSERT') and not has_table_privilege('authenticated','public.published_player_profiles','DELETE') and not has_table_privilege('service_role','public.published_player_profiles','UPDATE'),'direct mutation grants revoked including service role');
select pg_temp.pp_assert((select bool_and(relrowsecurity) from pg_class where oid in ('private.player_profile_versions'::regclass,'private.player_profile_commands'::regclass,'public.published_player_profiles'::regclass)),'all new tables have RLS');
set local role authenticated;
do $$declare n integer;begin for n in 3..23 loop perform public.confirm_player_profile(pg_temp.pp_command(100+n,2,n-1,'Histórico paginado'));end loop;end$$;
select public.get_player_profile_state(pg_temp.pp_id(1),0) as profile_first_page;
select public.get_player_profile_state(pg_temp.pp_id(1),20) as profile_last_page;
select pg_temp.pp_assert(jsonb_array_length(public.get_player_profile_state(pg_temp.pp_id(1))->'history')=20 and (public.get_player_profile_state(pg_temp.pp_id(1))->>'hasMore')::boolean,'first page is bounded and reports more');
select pg_temp.pp_assert(jsonb_array_length(public.get_player_profile_state(pg_temp.pp_id(1),20)->'history')=3 and not (public.get_player_profile_state(pg_temp.pp_id(1),20)->>'hasMore')::boolean,'remaining history not omitted');
select pg_temp.pp_error('select public.get_player_profile_state(pg_temp.pp_id(1),-1)','PT400');
reset role;
update public.admin_access set enabled=false;
set local role authenticated;
select pg_temp.pp_error('select public.confirm_player_profile(pg_temp.pp_command())','PT403');
select pg_temp.pp_error('select public.get_player_profile_state(pg_temp.pp_id(1))','PT403');
select pg_temp.pp_error('select public.get_player_profile_state(pg_temp.pp_id(1),-1)','PT403');
reset role;
rollback;
